class RobotAdapter(ABC):
    """Boundary between deterministic orchestration and a robot transport."""

    @abstractmethod
    def start_experiment(self, targets: Mapping[str, Pose2D], max_speed_mps: float) -> None:
        raise NotImplementedError

    @abstractmethod
    def stop_all(self, reason: str) -> None:
        raise NotImplementedError

    @abstractmethod
    def get_robot_states(self, robot_ids: Sequence[str]) -> Dict[str, RobotState]:
        raise NotImplementedError


@dataclass
class _MockTelemetry:
    x_m: float
    y_m: float
    speed_mps: float
    last_heartbeat_s: float
    stopped: bool = True


class MockRobotAdapter(RobotAdapter):
    """In-memory adapter used by tests and the dependency-free Mock Server."""

    def __init__(self, clock: Callable[[], float] = time.monotonic) -> None:
        self._clock = clock
        self._lock = threading.RLock()
        self._robots: Dict[str, _MockTelemetry] = {}
        self.stop_count = 0
        self.last_stop_reason: Optional[str] = None

    def start_experiment(self, targets: Mapping[str, Pose2D], max_speed_mps: float) -> None:
        now = self._clock()
        with self._lock:
            for robot_id, target in targets.items():
                self._robots[robot_id] = _MockTelemetry(
                    x_m=target.x_m,
                    y_m=target.y_m,
                    speed_mps=0.0,
                    last_heartbeat_s=now,
                    stopped=False,
                )

    def stop_all(self, reason: str) -> None:
        with self._lock:
            self.stop_count += 1
            self.last_stop_reason = reason
            for robot in self._robots.values():
                robot.speed_mps = 0.0
                robot.stopped = True

    def get_robot_states(self, robot_ids: Sequence[str]) -> Dict[str, RobotState]:
        now = self._clock()
        with self._lock:
            return {
                robot_id: RobotState(
                    robot_id=robot_id,
                    x_m=self._robots[robot_id].x_m,
                    y_m=self._robots[robot_id].y_m,
                    speed_mps=self._robots[robot_id].speed_mps,
                    heartbeat_age_s=max(0.0, now - self._robots[robot_id].last_heartbeat_s),
                    stopped=self._robots[robot_id].stopped,
                )
                for robot_id in robot_ids
                if robot_id in self._robots
            }

    def set_state(
        self,
        robot_id: str,
        *,
        x_m: Optional[float] = None,
        y_m: Optional[float] = None,
        speed_mps: Optional[float] = None,
        heartbeat: bool = False,
        last_heartbeat_s: Optional[float] = None,
    ) -> None:
        """Test/simulator hook for injecting telemetry."""
        with self._lock:
            robot = self._robots[robot_id]
            if x_m is not None:
                robot.x_m = x_m
            if y_m is not None:
                robot.y_m = y_m
            if speed_mps is not None:
                robot.speed_mps = speed_mps
            if heartbeat:
                robot.last_heartbeat_s = self._clock()
            if last_heartbeat_s is not None:
                robot.last_heartbeat_s = last_heartbeat_s


