@dataclass(frozen=True)
class _ActiveExperiment:
    experiment_id: str
    robot_ids: Sequence[str]
    started_at_s: float
    duration_s: float
    requested_max_speed_mps: float


class SafetySupervisor:
    """Independent deterministic safety loop; it never calls an LLM."""

    def __init__(
        self,
        adapter: RobotAdapter,
        on_stop: Callable[[str, ExperimentStatus, str], None],
        config: SafetyConfig = SafetyConfig(),
        clock: Callable[[], float] = time.monotonic,
        start_background: bool = True,
    ) -> None:
        self.adapter = adapter
        self.on_stop = on_stop
        self.config = config
        self._clock = clock
        self._lock = threading.RLock()
        self._active: Optional[_ActiveExperiment] = None
        self._global_estop = False
        self._shutdown = threading.Event()
        self._thread: Optional[threading.Thread] = None
        if start_background:
            self._thread = threading.Thread(
                target=self._run,
                name="safety-supervisor",
                daemon=True,
            )
            self._thread.start()

    def activate(
        self,
        experiment_id: str,
        robot_ids: Sequence[str],
        started_at_s: float,
        duration_s: float,
        requested_max_speed_mps: float,
    ) -> None:
        with self._lock:
            if self._global_estop:
                raise RuntimeError("global emergency stop is active")
            self._active = _ActiveExperiment(
                experiment_id=experiment_id,
                robot_ids=tuple(robot_ids),
                started_at_s=started_at_s,
                duration_s=duration_s,
                requested_max_speed_mps=requested_max_speed_mps,
            )

    def deactivate(self, experiment_id: str) -> None:
        with self._lock:
            if self._active and self._active.experiment_id == experiment_id:
                self._active = None

    def set_global_emergency_stop(self, active: bool = True) -> None:
        with self._lock:
            self._global_estop = active
        if active:
            self.check_once()

    @property
    def global_emergency_stop(self) -> bool:
        with self._lock:
            return self._global_estop

    def check_once(self) -> Optional[str]:
        with self._lock:
            active = self._active
            estop = self._global_estop
        if active is None:
            return None

        if estop:
            return self._violate(active, ExperimentStatus.SAFETY_STOPPED, "global emergency stop")

        now = self._clock()
        if now - active.started_at_s >= active.duration_s:
            return self._violate(active, ExperimentStatus.TIMED_OUT, "experiment duration elapsed")

        states = self.adapter.get_robot_states(active.robot_ids)
        missing = sorted(set(active.robot_ids) - set(states))
        if missing:
            return self._violate(
                active,
                ExperimentStatus.SAFETY_STOPPED,
                "missing robot telemetry: " + ", ".join(missing),
            )

        for robot_id in active.robot_ids:
            state = states[robot_id]
            if state.heartbeat_age_s > self.config.heartbeat_timeout_s:
                return self._violate(
                    active,
                    ExperimentStatus.SAFETY_STOPPED,
                    "heartbeat timeout: {} ({:.3f}s)".format(robot_id, state.heartbeat_age_s),
                )
            speed_limit = min(active.requested_max_speed_mps, self.config.absolute_max_speed_mps)
            if abs(state.speed_mps) > speed_limit:
                return self._violate(
                    active,
                    ExperimentStatus.SAFETY_STOPPED,
                    "speed limit exceeded: {} ({:.3f}m/s > {:.3f}m/s)".format(
                        robot_id, abs(state.speed_mps), speed_limit
                    ),
                )
            if not (
                self.config.min_x_m <= state.x_m <= self.config.max_x_m
                and self.config.min_y_m <= state.y_m <= self.config.max_y_m
            ):
                return self._violate(
                    active,
                    ExperimentStatus.SAFETY_STOPPED,
                    "field boundary exceeded: {} ({:.3f}, {:.3f})".format(
                        robot_id, state.x_m, state.y_m
                    ),
                )

        for first_id, second_id in combinations(active.robot_ids, 2):
            first, second = states[first_id], states[second_id]
            distance = math.hypot(first.x_m - second.x_m, first.y_m - second.y_m)
            if distance < self.config.min_safe_distance_m:
                return self._violate(
                    active,
                    ExperimentStatus.SAFETY_STOPPED,
                    "robots too close: {}/{} ({:.3f}m < {:.3f}m)".format(
                        first_id, second_id, distance, self.config.min_safe_distance_m
                    ),
                )
        return None

    def _violate(
        self,
        active: _ActiveExperiment,
        status: ExperimentStatus,
        reason: str,
    ) -> str:
        with self._lock:
            if self._active is None or self._active.experiment_id != active.experiment_id:
                return reason
            self._active = None
        self.adapter.stop_all(reason)
        self.on_stop(active.experiment_id, status, reason)
        return reason

    def _run(self) -> None:
        period_s = 1.0 / self.config.check_hz
        while not self._shutdown.wait(period_s):
            try:
                self.check_once()
            except Exception as exc:  # Fail closed if telemetry/adapter code fails.
                with self._lock:
                    active = self._active
                if active is not None:
                    self._violate(
                        active,
                        ExperimentStatus.SAFETY_STOPPED,
                        "safety supervisor error: {}".format(exc),
                    )

    def shutdown(self) -> None:
        self._shutdown.set()
        if self._thread is not None:
            self._thread.join(timeout=2.0)

