import time
from typing import Callable, Dict, List, Optional

from .adapters import MockRobotAdapter, RobotAdapter
from .formation import plan_square_formation
from .models import ExperimentRequest, ExperimentState, ExperimentStatus
from .safety import SafetyConfig, SafetySupervisor


class ExperimentManagerError(RuntimeError):
    pass


class ExperimentManager:
    def __init__(
        self,
        adapter: Optional[RobotAdapter] = None,
        safety_config: SafetyConfig = SafetyConfig(),
        clock: Callable[[], float] = time.monotonic,
        start_safety_thread: bool = True,
    ) -> None:
        self._clock = clock
        self.adapter = adapter or MockRobotAdapter(clock=clock)
        self.safety_config = safety_config
        self._lock = threading.RLock()
        self._experiments: Dict[str, ExperimentState] = {}
        self.safety_supervisor = SafetySupervisor(
            adapter=self.adapter,
            on_stop=self._on_safety_stop,
            config=safety_config,
            clock=clock,
            start_background=start_safety_thread,
        )

    def validate_experiment(self, request: ExperimentRequest) -> ExperimentState:
        errors: List[str] = []
        if not request.experiment_id.strip():
            errors.append("experiment_id must not be empty")
        if len(request.robot_ids) != 4:
            errors.append("square formation requires exactly 4 robots")
        if len(set(request.robot_ids)) != len(request.robot_ids):
            errors.append("robot_ids must be unique")
        if any(not str(robot_id).strip() for robot_id in request.robot_ids):
            errors.append("robot_ids must not contain empty values")
        if request.formation.lower() != "square":
            errors.append("formation must be 'square'")
        if not math.isfinite(request.spacing_m) or request.spacing_m <= 0:
            errors.append("spacing_m must be greater than 0")
        elif request.spacing_m < self.safety_config.min_safe_distance_m:
            errors.append("spacing_m must be at least the minimum safe distance")
        if not math.isfinite(request.duration_s) or request.duration_s <= 0:
            errors.append("duration_s must be greater than 0")
        if not math.isfinite(request.max_speed_mps) or request.max_speed_mps <= 0:
            errors.append("max_speed_mps must be greater than 0")
        elif request.max_speed_mps > self.safety_config.absolute_max_speed_mps:
            errors.append("max_speed_mps exceeds the configured absolute speed limit")
        if not request.coordinate_frame.strip():
            errors.append("coordinate_frame must not be empty")
        if not all(
            math.isfinite(value)
            for value in (request.center_x_m, request.center_y_m, request.orientation_deg)
        ):
            errors.append("center and orientation values must be finite")

        targets = {}
        if not errors:
            targets = plan_square_formation(
                request.robot_ids,
                request.spacing_m,
                request.center_x_m,
                request.center_y_m,
                request.orientation_deg,
            )
            for target in targets.values():
                if not (
                    self.safety_config.min_x_m <= target.x_m <= self.safety_config.max_x_m
                    and self.safety_config.min_y_m <= target.y_m <= self.safety_config.max_y_m
                ):
                    errors.append("planned square lies outside the configured field boundary")
                    targets = {}
                    break

        return ExperimentState(
            request=request,
            status=ExperimentStatus.INVALID if errors else ExperimentStatus.VALIDATED,
            validation_errors=errors,
            targets=targets,
        )

    def start_experiment(self, request: ExperimentRequest) -> ExperimentState:
        validated = self.validate_experiment(request)
        if validated.validation_errors:
            raise ExperimentManagerError("validation failed: " + "; ".join(validated.validation_errors))
        with self._lock:
            if request.experiment_id in self._experiments:
                raise ExperimentManagerError(
                    "experiment_id already exists and cannot be started twice: " + request.experiment_id
                )
            if any(state.status == ExperimentStatus.RUNNING for state in self._experiments.values()):
                raise ExperimentManagerError("another experiment is already running")
            now = self._clock()
            validated.status = ExperimentStatus.CREATED
            validated.created_at_s = now
            self._experiments[request.experiment_id] = validated
            try:
                self.adapter.start_experiment(validated.targets, request.max_speed_mps)
                validated.status = ExperimentStatus.RUNNING
                validated.started_at_s = now
                self.safety_supervisor.activate(
                    experiment_id=request.experiment_id,
                    robot_ids=request.robot_ids,
                    started_at_s=now,
                    duration_s=request.duration_s,
                    requested_max_speed_mps=request.max_speed_mps,
                )
            except Exception as exc:
                validated.status = ExperimentStatus.FAILED
                validated.stopped_at_s = self._clock()
                validated.stop_reason = "start failed: {}".format(exc)
                self.adapter.stop_all(validated.stop_reason)
                raise ExperimentManagerError(validated.stop_reason) from exc
        return self.get_experiment_status(request.experiment_id)

    def stop_experiment(self, experiment_id: str, reason: str = "manual stop") -> ExperimentState:
        with self._lock:
            state = self._require(experiment_id)
            if state.status in {
                ExperimentStatus.STOPPED,
                ExperimentStatus.TIMED_OUT,
                ExperimentStatus.SAFETY_STOPPED,
                ExperimentStatus.FAILED,
            }:
                return self._snapshot(state)
            self.safety_supervisor.deactivate(experiment_id)
            self.adapter.stop_all(reason)
            state.status = ExperimentStatus.STOPPED
            state.stopped_at_s = self._clock()
            state.stop_reason = reason
            return self._snapshot_with_telemetry(state)

    def get_experiment_status(self, experiment_id: str) -> ExperimentState:
        with self._lock:
            state = self._require(experiment_id)
            return self._snapshot_with_telemetry(state)

    def _on_safety_stop(
        self,
        experiment_id: str,
        status: ExperimentStatus,
        reason: str,
    ) -> None:
        with self._lock:
            state = self._experiments.get(experiment_id)
            if state is None or state.status != ExperimentStatus.RUNNING:
                return
            state.status = status
            state.stopped_at_s = self._clock()
            state.stop_reason = reason
            state.robot_states = self.adapter.get_robot_states(state.request.robot_ids)

    def _snapshot_with_telemetry(self, state: ExperimentState) -> ExperimentState:
        state.robot_states = self.adapter.get_robot_states(state.request.robot_ids)
        return self._snapshot(state)

    @staticmethod
    def _snapshot(state: ExperimentState) -> ExperimentState:
        return copy.deepcopy(state)

    def _require(self, experiment_id: str) -> ExperimentState:
        try:
            return self._experiments[experiment_id]
        except KeyError as exc:
            raise ExperimentManagerError("unknown experiment_id: " + experiment_id) from exc

    def shutdown(self) -> None:
        self.safety_supervisor.shutdown()

    def __enter__(self) -> "ExperimentManager":
        return self

    def __exit__(self, exc_type, exc_value, traceback) -> None:
        self.shutdown()

