import threading
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Dict, Optional

from .manager import ExperimentManager, ExperimentManagerError
from .service import MCP_TOOLS, ExperimentService


class ControlHTTPServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, server_address, service: ExperimentService):
        super().__init__(server_address, ControlRequestHandler)
        self.service = service


class ControlRequestHandler(BaseHTTPRequestHandler):
    server: ControlHTTPServer
    protocol_version = "HTTP/1.1"

    def do_GET(self) -> None:
        if self.path == "/health":
            self._send_json(HTTPStatus.OK, {"ok": True, "service": "openvela-ros2-control"})
            return
        self._send_json(HTTPStatus.NOT_FOUND, {"error": "not found"})

    def do_POST(self) -> None:
        try:
            body = self._read_json()
            if self.path == "/mcp":
                self._handle_mcp(body)
                return
            prefix = "/api/tools/"
            if self.path.startswith(prefix):
                tool_name = self.path[len(prefix) :]
                result = self.server.service.call_tool(tool_name, body)
                self._send_json(HTTPStatus.OK, result)
                return
            self._send_json(HTTPStatus.NOT_FOUND, {"error": "not found"})
        except (ExperimentManagerError, ValueError, TypeError, KeyError) as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
        except json.JSONDecodeError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid JSON: {}".format(exc)})

    def _handle_mcp(self, message: Dict[str, Any]) -> None:
        request_id = message.get("id")
        method = message.get("method")
        try:
            if method == "initialize":
                result: Dict[str, Any] = {
                    "protocolVersion": "2025-03-26",
                    "capabilities": {"tools": {"listChanged": False}},
                    "serverInfo": {"name": "openvela-ros2-control", "version": "0.1.0"},
                }
            elif method == "notifications/initialized":
                self._send_empty(HTTPStatus.ACCEPTED)
                return
            elif method == "ping":
                result = {}
            elif method == "tools/list":
                result = {"tools": MCP_TOOLS}
            elif method == "tools/call":
                params = message.get("params", {})
                payload = self.server.service.call_tool(
                    str(params.get("name", "")), dict(params.get("arguments", {}))
                )
                encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
                result = {
                    "content": [{"type": "text", "text": encoded}],
                    "structuredContent": payload,
                    "isError": False,
                }
            else:
                self._send_json(
                    HTTPStatus.OK,
                    {
                        "jsonrpc": "2.0",
                        "id": request_id,
                        "error": {"code": -32601, "message": "method not found: {}".format(method)},
                    },
                    mcp=True,
                )
                return
            self._send_json(
                HTTPStatus.OK,
                {"jsonrpc": "2.0", "id": request_id, "result": result},
                mcp=True,
            )
        except (ExperimentManagerError, ValueError, TypeError, KeyError) as exc:
            self._send_json(
                HTTPStatus.OK,
                {
                    "jsonrpc": "2.0",
                    "id": request_id,
                    "error": {"code": -32000, "message": str(exc)},
                },
                mcp=True,
            )

    def _read_json(self) -> Dict[str, Any]:
        length = int(self.headers.get("Content-Length", "0"))
        raw = self.rfile.read(length)
        value = json.loads(raw.decode("utf-8"))
        if not isinstance(value, dict):
            raise ValueError("JSON body must be an object")
        return value

    def _send_json(self, status: HTTPStatus, body: Dict[str, Any], mcp: bool = False) -> None:
        encoded = json.dumps(body, ensure_ascii=False, indent=2).encode("utf-8")
        self.send_response(status)
        self.send_header(
            "Content-Type",
            "application/json; charset=utf-8" if not mcp else "application/json",
        )
        self.send_header("Content-Length", str(len(encoded)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(encoded)

    def _send_empty(self, status: HTTPStatus) -> None:
        self.send_response(status)
        self.send_header("Content-Length", "0")
        self.send_header("Connection", "close")
        self.end_headers()

    def log_message(self, fmt: str, *args: Any) -> None:
        print("{} - {}".format(self.address_string(), fmt % args))


def create_server(host: str = "0.0.0.0", port: int = 8765) -> ControlHTTPServer:
    manager = ExperimentManager(start_safety_thread=True)
    return ControlHTTPServer((host, port), ExperimentService(manager))


def main(argv: Optional[list] = None) -> int:
    parser = argparse.ArgumentParser(description="OpenVela ROS2 control Mock MCP/HTTP server")
    parser.add_argument("--host", default="0.0.0.0")
    parser.add_argument("--port", default=8765, type=int)
    args = parser.parse_args(argv)
    server = create_server(args.host, args.port)

    stopping = threading.Event()

    def request_shutdown(signum, frame) -> None:
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGINT, request_shutdown)
    if hasattr(signal, "SIGTERM"):
        signal.signal(signal.SIGTERM, request_shutdown)
    print("Mock MCP/HTTP server listening on http://{}:{}/mcp".format(args.host, args.port))
    try:
        server.serve_forever()
    finally:
        server.service.manager.shutdown()
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

from typing import Any, Dict

from .manager import ExperimentManager
from .models import ExperimentRequest


class ExperimentService:
    """Protocol-neutral application service exposed by MCP and REST."""

    def __init__(self, manager: ExperimentManager) -> None:
        self.manager = manager

    def validate_experiment(self, arguments: Dict[str, Any]) -> Dict[str, Any]:
        return self.manager.validate_experiment(ExperimentRequest.from_dict(arguments)).to_dict()

    def start_experiment(self, arguments: Dict[str, Any]) -> Dict[str, Any]:
        return self.manager.start_experiment(ExperimentRequest.from_dict(arguments)).to_dict()

    def stop_experiment(self, arguments: Dict[str, Any]) -> Dict[str, Any]:
        return self.manager.stop_experiment(
            str(arguments.get("experiment_id", "")),
            str(arguments.get("reason", "manual stop")),
        ).to_dict()

    def get_experiment_status(self, arguments: Dict[str, Any]) -> Dict[str, Any]:
        return self.manager.get_experiment_status(
            str(arguments.get("experiment_id", ""))
        ).to_dict()

    def call_tool(self, name: str, arguments: Dict[str, Any]) -> Dict[str, Any]:
        tools = {
            "validate_experiment": self.validate_experiment,
            "start_experiment": self.start_experiment,
            "stop_experiment": self.stop_experiment,
            "get_experiment_status": self.get_experiment_status,
        }
        if name not in tools:
            raise ValueError("unknown tool: " + name)
